window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-87b2643eb03a7807"]={"versions": [{"id": "FIG-87b2643eb03a7807", "releases": ["R4.1.3", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitverlaufs- und Randbedingungsdiagramm (Timing Constraint Timeline / Event Occurrence Trace).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, identisch anwendbar auf Adaptive und Classic Platform).</li>\n<li><strong>Funktionaler Zweck:</strong> Formale Semantik- und Validierungsdarstellung des Metamodell-Elements <code>PeriodicEventTriggering</code> (Spezialisierung von <code>EventTriggeringConstraint</code>). Das Diagramm illustriert das Kriterium einer Constraint-Verletzung innerhalb eines definierten Beobachtungsfensters (<code>Time Interval Observation</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Entitäten (<code>AUTOSAR MM::TimingExtensions</code>):</strong></li>\n<li><code>PeriodicEventTriggering</code> («atpPrototype» / Metaklasse): Definiert die zeitlichen Schranken periodisch auftretender Ereignisse.</li>\n<li><code>period</code>: Nominale Periodendauer zwischen den Referenzzeitpunkten aufeinanderfolgender Ereignisfenster (im Diagramm: 6 Zeiteinheiten bzw. 3 Skalenschritte).</li>\n<li><code>jitter</code>: Maximal zulässige zeitliche Streuung/Toleranzfenster ab Periodenbeginn (grau hinterlegtes Intervall $[k \\cdot \\text{Period}, k \\cdot \\text{Period} + \\text{Jitter}]$; im Diagramm: 2 Zeiteinheiten).</li>\n<li><code>TimingDescriptionEvent</code>: Abstraktes Ereignis (z. B. OS-Task-Aktivierung, <code>ara::com</code> Service-Event-Empfang, RTE-Runnable-Trigger).</li>\n<li><strong>Graphische Notationselemente:</strong></li>\n<li><strong>Graue Rechtecke:</strong> Gültige Auftrittsintervalle (Akzeptanzfenster) der Größe <code>Jitter</code>, jeweils beabstandet um <code>Period</code>.</li>\n<li><strong>Schwarze Pfeile (<code>Event Occurrence 1..7</code>):</strong> Diskrete Zeitpunkte $t_n$ des realen Eintreffens des Ereignisses.</li>\n<li><strong>Gestrichelter Rahmen (<code>Time Interval Observation</code>):</strong> Beobachtungsintervall $[t_{\\text{start observation}}, t_{\\text{end observation}}]$.</li>\n<li><strong>$t_{\\text{reference}}$:</strong> Virtueller Referenzzeitpunkt für den Phasenabgleich des periodischen Rasters.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Mathematische Randbedingung:</strong></li>\n</ul>\n<p class=\"fig-p\">Ein Ereignisstrom erfüllt <code>PeriodicEventTriggering</code> genau dann, wenn eine Referenzzeit $t_{\\text{reference}}$ existiert, sodass für jede $n$-te Ereignisausprägung im Beobachtungsfenster gilt:</p>\n<p class=\"fig-p\">$$(n - 1) \\cdot \\text{Period} \\le t_n - t_{\\text{reference}} \\le (n - 1) \\cdot \\text{Period} + \\text{Jitter}$$</p>\n<ul class=\"fig-list\">\n<li><strong>Ablauf & Fehleranalyse:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ereignisse 1 bis 4:</strong> Treffen innerhalb ihrer jeweiligen Jitter-Fenster $[0, 2]$, $[6, 8]$, $[12, 14]$ und $[18, 20]$ ein. Die Bedingung ist bis $n = 4$ erfüllt.</li>\n<li><strong>Ereignis 5 (Constraint-Verletzung):</strong> Tritt vor Beginn seines zugehörigen Fensters auf ($t_5 \\approx 23$, während das Fenster erst bei $t = 24$ startet).</li>\n<li><strong>Konsequenz:</strong> Da kein global verschobenes $t_{\\text{reference}}$ existiert, das <em>alle</em> Ereignisse 1 bis 6 simultan in ihre jeweiligen Fenster einpasst, ist das Constraint für das Beobachtungsfenster verletzt (<code>Violation of Period and Jitter</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timing-Analyse & Scheduling-Synthese:</strong></li>\n<li>Werkzeuge zur Timing-Verifikation (z. B. SymTA/S, INCHRON) nutzen dieses Kriterium zur Verifikation von Task-Aktivierungsquellen, Kommunikationspfaden (<code>ara::com</code> Field Notifications, SOME/IP Events) und End-to-End-Laufzeitketten (Event Chains).</li>\n<li><strong>Stack- und Anwendungs-Implementierung:</strong></li>\n<li><strong>Classic Platform:</strong> Verletzungen weisen auf ungenaue OS-Alarm-Konfigurationen, Jitter-Akkumulation durch Interrupt-Sperrzeiten (CAT2-ISRs) oder Zykluszeitdrifts in Hardwareschnittstellen (CAN/FlexRay-Dispatching) hin.</li>\n<li><strong>Adaptive Platform:</strong> Signalisiert Scheduling-Latenzen im OS (POSIX FIFO/RR Scheduling Latencies), Thread-Drifts durch unzureichende Monotonic-Clock-Synchronisation (<code>CLOCK_MONOTONIC</code>) oder Buffer-Queueing in der IPC-/Netzwerkkommunikation.</li>\n<li><strong>Diagnose & Laufzeitüberwachung:</strong></li>\n<li>Kann zur Laufzeit über Watchdogs, Timing Monitoring Hooks oder Execution Management zur Auslösung von Safe-States bzw. Det/Dem-Fehlereinträgen (<code>TIMING_VIOLATION</code>) herangezogen werden.</li>\n</ul>"}, {"id": "FIG-5f952a74022fcbe2", "releases": ["R4.2.2", "R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Zeitverlaufs- und Randbedingungsdiagramm (Timing Constraint Timeline / Event Occurrence Trace).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>TPS_TimingExtensions</code>, identisch anwendbar auf Adaptive und Classic Platform).</li>\n<li><strong>Funktionaler Zweck:</strong> Formale Semantik- und Validierungsdarstellung des Metamodell-Elements <code>PeriodicEventTriggering</code> (Spezialisierung von <code>EventTriggeringConstraint</code>). Das Diagramm illustriert das Kriterium einer Constraint-Verletzung innerhalb eines definierten Beobachtungsfensters (<code>Time Interval Observation</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Entitäten (<code>AUTOSAR MM::TimingExtensions</code>):</strong></li>\n<li><code>PeriodicEventTriggering</code> («atpPrototype» / Metaklasse): Definiert die zeitlichen Schranken periodisch auftretender Ereignisse.</li>\n<li><code>period</code>: Nominale Periodendauer zwischen den Referenzzeitpunkten aufeinanderfolgender Ereignisfenster (im Diagramm: 6 Zeiteinheiten bzw. 3 Skalenschritte).</li>\n<li><code>jitter</code>: Maximal zulässige zeitliche Streuung/Toleranzfenster ab Periodenbeginn (grau hinterlegtes Intervall $[k \\cdot \\text{Period}, k \\cdot \\text{Period} + \\text{Jitter}]$; im Diagramm: 2 Zeiteinheiten).</li>\n<li><code>TimingDescriptionEvent</code>: Abstraktes Ereignis (z. B. OS-Task-Aktivierung, <code>ara::com</code> Service-Event-Empfang, RTE-Runnable-Trigger).</li>\n<li><strong>Graphische Notationselemente:</strong></li>\n<li><strong>Graue Rechtecke:</strong> Gültige Auftrittsintervalle (Akzeptanzfenster) der Größe <code>Jitter</code>, jeweils beabstandet um <code>Period</code>.</li>\n<li><strong>Schwarze Pfeile (<code>Event Occurrence 1..7</code>):</strong> Diskrete Zeitpunkte $t_n$ des realen Eintreffens des Ereignisses.</li>\n<li><strong>Gestrichelter Rahmen (<code>Time Interval Observation</code>):</strong> Beobachtungsintervall $[t_{\\text{start observation}}, t_{\\text{end observation}}]$.</li>\n<li><strong>$t_{\\text{reference}}$:</strong> Virtueller Referenzzeitpunkt für den Phasenabgleich des periodischen Rasters.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Mathematische Randbedingung:</strong></li>\n</ul>\n<p class=\"fig-p\">Ein Ereignisstrom erfüllt <code>PeriodicEventTriggering</code> genau dann, wenn eine Referenzzeit $t_{\\text{reference}}$ existiert, sodass für jede $n$-te Ereignisausprägung im Beobachtungsfenster gilt:</p>\n<p class=\"fig-p\">$$(n - 1) \\cdot \\text{Period} \\le t_n - t_{\\text{reference}} \\le (n - 1) \\cdot \\text{Period} + \\text{Jitter}$$</p>\n<ul class=\"fig-list\">\n<li><strong>Ablauf & Fehleranalyse:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ereignisse 1 bis 4:</strong> Treffen innerhalb ihrer jeweiligen Jitter-Fenster $[0, 2]$, $[6, 8]$, $[12, 14]$ und $[18, 20]$ ein. Die Bedingung ist bis $n = 4$ erfüllt.</li>\n<li><strong>Ereignis 5 (Constraint-Verletzung):</strong> Tritt vor Beginn seines zugehörigen Fensters auf ($t_5 \\approx 23$, während das Fenster erst bei $t = 24$ startet).</li>\n<li><strong>Konsequenz:</strong> Da kein global verschobenes $t_{\\text{reference}}$ existiert, das <em>alle</em> Ereignisse 1 bis 6 simultan in ihre jeweiligen Fenster einpasst, ist das Constraint für das Beobachtungsfenster verletzt (<code>Violation of Period and Jitter</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timing-Analyse & Scheduling-Synthese:</strong></li>\n<li>Werkzeuge zur Timing-Verifikation (z. B. SymTA/S, INCHRON) nutzen dieses Kriterium zur Verifikation von Task-Aktivierungsquellen, Kommunikationspfaden (<code>ara::com</code> Field Notifications, SOME/IP Events) und End-to-End-Laufzeitketten (Event Chains).</li>\n<li><strong>Stack- und Anwendungs-Implementierung:</strong></li>\n<li><strong>Classic Platform:</strong> Verletzungen weisen auf ungenaue OS-Alarm-Konfigurationen, Jitter-Akkumulation durch Interrupt-Sperrzeiten (CAT2-ISRs) oder Zykluszeitdrifts in Hardwareschnittstellen (CAN/FlexRay-Dispatching) hin.</li>\n<li><strong>Adaptive Platform:</strong> Signalisiert Scheduling-Latenzen im OS (POSIX FIFO/RR Scheduling Latencies), Thread-Drifts durch unzureichende Monotonic-Clock-Synchronisation (<code>CLOCK_MONOTONIC</code>) oder Buffer-Queueing in der IPC-/Netzwerkkommunikation.</li>\n<li><strong>Diagnose & Laufzeitüberwachung:</strong></li>\n<li>Kann zur Laufzeit über Watchdogs, Timing Monitoring Hooks oder Execution Management zur Auslösung von Safe-States bzw. Det/Dem-Fehlereinträgen (<code>TIMING_VIOLATION</code>) herangezogen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-87b2643eb03a7807", "to": "FIG-5f952a74022fcbe2", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5f952a74022fcbe2", "to": "FIG-87b2643eb03a7807", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
